-- ENRIQUE FREE V51 SECURE BOOT
local Players=game:GetService("Players")
local LocalPlayer=Players.LocalPlayer
while not LocalPlayer do task.wait() LocalPlayer=Players.LocalPlayer end
local function copy_text(text)
 text=tostring(text or "")
 local ok,result=pcall(function()
  if setclipboard then return setclipboard(text) end
  if toclipboard then return toclipboard(text) end
  if syn and syn.clipboard_set then return syn.clipboard_set(text) end
  if writeclipboard then return writeclipboard(text) end
  return false
 end)
 return ok and result~=false
end
local bootMsg,bootButton
local function fail(msg)
 msg=tostring(msg)
 print("[ENRIQUE]",msg) if warn then warn("[ENRIQUE] "..msg) end
 pcall(function()
  if not bootMsg then
   local g=Instance.new("ScreenGui") g.Name="ENRIQUE_BOOT" g.ResetOnSpawn=false g.IgnoreGuiInset=true g.Parent=LocalPlayer:WaitForChild("PlayerGui",5)
   local f=Instance.new("Frame",g) f.AnchorPoint=Vector2.new(.5,.5) f.Position=UDim2.fromScale(.5,.5) f.Size=UDim2.fromOffset(340,112) f.BackgroundColor3=Color3.fromRGB(12,6,24) Instance.new("UICorner",f).CornerRadius=UDim.new(0,10)
   bootMsg=Instance.new("TextLabel",f) bootMsg.Position=UDim2.fromOffset(12,8) bootMsg.Size=UDim2.new(1,-24,0,58) bootMsg.BackgroundTransparency=1 bootMsg.TextWrapped=true bootMsg.TextXAlignment=Enum.TextXAlignment.Left bootMsg.TextYAlignment=Enum.TextYAlignment.Top bootMsg.Font=Enum.Font.GothamBold bootMsg.TextSize=14 bootMsg.TextColor3=Color3.new(1,1,1)
   bootButton=Instance.new("TextButton",f) bootButton.AnchorPoint=Vector2.new(.5,1) bootButton.Position=UDim2.new(.5,0,1,-10) bootButton.Size=UDim2.fromOffset(140,28) bootButton.Text="COPY ERROR" bootButton.Font=Enum.Font.GothamBold bootButton.TextSize=14 bootButton.TextColor3=Color3.fromRGB(20,10,35) bootButton.BackgroundColor3=Color3.fromRGB(180,120,255) bootButton.BorderSizePixel=0 Instance.new("UICorner",bootButton).CornerRadius=UDim.new(0,8)
   bootButton.MouseButton1Click:Connect(function() local ok=copy_text(bootMsg and bootMsg.Text or "ENRIQUE ERROR") bootButton.Text=ok and "COPIED" or "NO SUPPORT" task.delay(1.2,function() if bootButton then bootButton.Text="COPY ERROR" end end) end)
  end
  bootMsg.Text="ENRIQUE ERROR: "..msg
 end)
end
